def format_bytes(n):
    """Return a human-readable byte size string, e.g. '1.5 KB'."""
    for unit, exp in [("TB", 12), ("GB", 9), ("MB", 6), ("KB", 3)]:
        if n >= 1024 ** exp:
            value = n / (1024 ** exp)
            if value == int(value):
                return f"{int(value)} {unit}"
            return f"{value:.1f} {unit}"
    return f"{n} B"
